import os
from six import add_metaclass
from abc import ABCMeta, abstractmethod
from taf.ul.sc.util import util  # type: ignore


@add_metaclass(ABCMeta)
class GenericUe(object):

    def collect_info(self):
        ue_info = {'sw_version': self.get_version(),
                   'ue_type': self.get_ue_type()}
        return ue_info

    def prepare(self):
        # full preparation eg: restart executor, copy needed files like rtg.ini scenario
        pass

    def start_recovery_observers(self):
        pass

    def stop_recovery_observers(self):
        pass

    @abstractmethod
    def synchronize_bts_link(self):
        pass

    @abstractmethod
    def start_scenario(self):
        pass

    @abstractmethod
    def stop_scenario(self):
        pass

    @abstractmethod
    def copy_scenario_file(self, source_scenario_path, destination_dir):
        util().upload_files(local_dir=os.path.dirname(source_scenario_path),
                            local_file=os.path.basename(source_scenario_path),
                            remote_device_name=self.ws_name,
                            remote_dir=destination_dir,
                            log_level='error')

    @abstractmethod
    def collect_configuration(self, destination_dir):
        pass

    @abstractmethod
    def collect_report(self, destination_dir):
        pass

    @abstractmethod
    def is_scenario_running(self):
        pass

    @abstractmethod
    def restart(self):
        pass
